lessons.code:
WITH ranked AS (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS position
  FROM employees WHERE salary IS NOT NULL
)
SELECT MAX(salary) AS third_salary FROM ranked WHERE position = 3;

